import { Component, EventEmitter, Output } from '@angular/core';
declare var bootstrap: any;
@Component({
  selector: 'app-qracceso',
  standalone: false,
  templateUrl: './qracceso.component.html',
  styleUrl: './qracceso.component.scss'
})
export class QraccesoComponent {
    @Output() closeModal: EventEmitter<void> = new EventEmitter<void>();
    title = 'Tasa de cambio BCV';
   
  
    constructor(
    ) { }
  
    ngOnInit(): void {
     
    }
  
  onClose() {
    this.closeAndCleanup();
    this.closeModal.emit();
  }

  // Función auxiliar para no repetir el código de limpieza de Bootstrap
  private closeAndCleanup() {
    const modalElement = document.getElementById('viewQRPaciente') as HTMLElement;
    if (modalElement) {
      const bootstrapModal = (window as any).bootstrap?.Modal?.getInstance(modalElement);
      if (bootstrapModal) bootstrapModal.hide();
    }
    const backdrop = document.querySelector('.modal-backdrop');
    if (backdrop) backdrop.remove();
    document.body.classList.remove('modal-open');
    document.body.style.paddingRight = '';
    document.body.style.overflow = '';
    document.documentElement.style.overflow = '';
    document.documentElement.style.overflowX = 'auto';
  }


  imprimirRecipe() {
    // Crear una ventana flotante para la impresión
    const logoBase64 = 'data:image/svg+xml;base64,';
    const qrlogo = 'data:image/jpeg;base64,';
    const ventanaImpresion = window.open('', '_blank', 'width=800,height=600');


    if (ventanaImpresion) {
      ventanaImpresion.document.write(`
      <html>
        <head>
          <title>QR Paciente - Klyntic</title>
          <style>
            body { font-family: Arial, sans-serif; padding: 40px; color: #333; }
            
            /* Alineación perfecta para el logo y el título */
            .header { 
              text-align: center; 
              border-bottom: 2px solid #007bff; 
              padding-bottom: 15px; 
            }
            .logo-container {
              display: flex;
              align-items: center;
              justify-content: center;
              gap: 10px; /* Espacio entre el logo y el texto */
              margin-bottom: 5px;
            }
            .logoav {
              object-fit: contain;
            }
            
            .content { margin-top: 30px; font-size: 16px; line-height: 1.6; }
            .section { margin-bottom: 20px; }
            .qr-section { text-align: center; }
            .footer { margin-top: 50px; text-align: center; font-size: 12px; color: #777; border-top: 1px solid #ddd; padding-top: 10px; }
            h3 { color: #007bff; margin-bottom: 5px; }
          </style>
        </head>
        <body>
          <div class="header">
            <div class="logo-container">
              <img class="logoav" src="${logoBase64}" width="45" height="45" alt="Klyntic Logo">
              <h2>QR App Paciente</h2>
            </div>
            <p style="margin: 0; color: #555; font-weight: bold;">Klyntic App</p>
          </div>
          <div class="section qr-section">
              <h3>Qr Pacientes App:</h3>
              <img class="logoav" src="${qrlogo}"  alt="Klyntic Logo">
            </div>
          
          
          <div class="footer">
            <p>Qr generado digitalmente a través de Klyntic.</p>
          </div>
        </body>
      </html>
    `);

      ventanaImpresion.document.close();
      ventanaImpresion.focus();

      // Le damos un micro-retraso de 200 milisegundos para que el navegador cargue el logo antes de abrir la impresora
      setTimeout(() => {
        ventanaImpresion.print();
        ventanaImpresion.close();
      }, 200);
    }
  }
}
